import json, os, sys
named = ('packages/escher-driver/src/lint.rs', 'packages/escher-driver/src/mcp_tests.rs', 'tests/blitz-tests/tests/stand_requirement_sweep.rs', 'packages/blitz-dom/src/document.rs')
over, seen = [], set()
def walk(sp, f):
    if sp.get('kind') == 'function' and sp['metrics']['cognitive']['sum'] > 15:
        over.append((f, sp.get('name'), sp['metrics']['cognitive']['sum']))
    for c in sp.get('spaces') or []:
        walk(c, f)
for dp, _, fs in os.walk(sys.argv[1]):
    for n in fs:
        if n.endswith('.json'):
            d = json.load(open(os.path.join(dp, n), encoding='utf-8'))
            f = os.path.relpath(os.path.abspath(d['name'])).replace(os.sep, '/')
            if f not in seen:
                seen.add(f)
                walk(d, f)
for f, name, cog in sorted(over):
    if f in named:
        print(f, name, cog)
print('files read', len(seen))
print('over 15:', len(over))
PY

